import Cycles "mo:base/ExperimentalCycles";
import Principal "mo:base/Principal";
import HashMap "mo:base/HashMap";
import List "mo:base/List";
import NFTActorClass "../NFT/nft";

persistent actor OpenD {

  // NFT canister id -> the NFT actor itself
  transient var mapOfNFTs = HashMap.HashMap<Principal, NFTActorClass.NFT>(1, Principal.equal, Principal.hash);
  // owner principal -> list of NFT canister ids they own
  transient var mapOfOwners = HashMap.HashMap<Principal, List.List<Principal>>(1, Principal.equal, Principal.hash);

  public shared (msg) func mint(imgData : [Nat8], name : Text) : async Principal {
    let owner : Principal = msg.caller;
    Cycles.add(10_000_000_000_000);
    let newNFT = await NFTActorClass.NFT(name, owner, imgData);
    let newNFTPrincipal = await newNFT.getCanisterId();

    mapOfNFTs.put(newNFTPrincipal, newNFT);
    addToOwnershipMap(owner, newNFTPrincipal);

    return newNFTPrincipal;
  };

  private func addToOwnershipMap(owner : Principal, nftId : Principal) {
    var ownedNFTs : List.List<Principal> = switch (mapOfOwners.get(owner)) {
      case null List.nil<Principal>();
      case (?result) result;
    };
    ownedNFTs := List.push(nftId, ownedNFTs);
    mapOfOwners.put(owner, ownedNFTs);
  };

  public query func getOwnedNFTs(user : Principal) : async [Principal] {
    var userNFTs : List.List<Principal> = switch (mapOfOwners.get(user)) {
      case null List.nil<Principal>();
      case (?result) result;
    };
    return List.toArray(userNFTs);
  };
};

import React, { useEffect, useState } from "react";
import logo from "/logo.png";
import { BrowserRouter, Link, Switch, Route } from "react-router-dom";
import homeImage from "/home-img.png";
import Minter from "./Minter";
import Gallery from "./Gallery";
import { OPEND_backend } from "../../../declarations/OPEND_backend";
import CURRENT_USER_ID from "../main";

function Header() {
  const [userOwnedGallery, setOwnedGallery] = useState();

  async function getNFTs() {
    const userNFTIds = await OPEND_backend.getOwnedNFTs(CURRENT_USER_ID);
    setOwnedGallery(<Gallery title="My NFTs" ids={userNFTIds} />);
  }

  useEffect(() => { getNFTs(); }, []);

  return (
    <BrowserRouter forceRefresh={true}>
      <div className="app-root-1">
        <header className="...">
          <div className="...">
            <img className="header-logo-11" src={logo} />
            <Link to="/"><h5 className="header-logo-text">OpenD</h5></Link>
            <button className="..."><Link to="/discover">Discover</Link></button>
            <button className="..."><Link to="/minter">Minter</Link></button>
            <button className="..."><Link to="/collection">My NFTs</Link></button>
          </div>
        </header>
      </div>
      <Switch>
        <Route exact path="/"><img className="bottom-space" src={homeImage} /></Route>
        <Route path="/discover"><h1>Discover</h1></Route>
        <Route path="/minter"><Minter /></Route>
        <Route path="/collection">{userOwnedGallery}</Route>
      </Switch>
    </BrowserRouter>
  );
}
export default Header;

import React, { useEffect, useState } from "react";
import Item from "./Item";

function Gallery(props) {
  const [items, setItems] = useState();

  function fetchNFTs() {
    if (props.ids != undefined) {
      setItems(
        props.ids.map((NFTId) => <Item id={NFTId} key={NFTId.toText()} />)
      );
    }
  }

  useEffect(() => { fetchNFTs(); }, []);

  return (
    <div className="gallery-view">
      <h3 className="makeStyles-title-99 Typography-h3">{props.title}</h3>
      <div className="disGrid-root disGrid-container disGrid-spacing-xs-2">
        <div className="disGrid-root disGrid-item disGrid-grid-xs-12">
          <div className="disGrid-root disGrid-container disGrid-spacing-xs-5 disGrid-justify-content-xs-center">
            {items}
          </div>
        </div>
      </div>
    </div>
  );
}
export default Gallery;

